@GetMapping
    public Result<Map<String, Object>> list(
            @RequestParam(required = false) String keyword,
            @RequestParam(defaultValue = "1") int pageNum,
            @RequestParam(defaultValue = "20") int pageSize) {

        // 获取所有已登录的 loginId
        // Sa-Token searchSessionId 返回 Session key 列表，格式: "satoken:login:session:xxx"
        List<String> sessionIds = StpUtil.searchSessionId("", 0, -1, false);

        List<Map<String, Object>> users = new ArrayList<>();
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        Set<String> seenLoginIds = new HashSet<>();

        for (String sessionId : sessionIds) {
            try {
                SaSession session;
                try { session = StpUtil.getSessionBySessionId(sessionId); }
                catch (Exception ignored) { continue; }
                if (session == null) continue;

                String loginId = String.valueOf(session.getLoginId());
                // 去重：同一用户多设备只显示一次
                if (seenLoginIds.contains(loginId)) continue;
                seenLoginIds.add(loginId);

                String username = session.getString("username");
                String realName = session.getString("realName");

                // 关键词过滤
                if (keyword != null && !keyword.isBlank()) {
                    String kw = keyword.toLowerCase();
                    boolean match = (username != null && username.toLowerCase().contains(kw))
                            || (realName != null && realName.toLowerCase().contains(kw))
                            || loginId.contains(kw);
                    if (!match) continue;
                }

                // 获取该用户所有 token（多设备）。getTokenValueListByLoginId 返回的是
                // 插入顺序（最旧在前），且可能包含已失效但尚未 GC 的条目，所以这里：
                //  - 只统计仍有效（剩余 timeout > 0）的 token 作为“设备数”；
                //  - 取剩余有效期最大的那个（= 最新登录的设备）作为本行的代表，
                //    用于展示剩余有效期 / 登录时间，避免读到最旧 token 而显示“已过期”。
                List<String> tokens = StpUtil.getTokenValueListByLoginId(loginId);
                int activeCount = 0;
                String freshestToken = null;
                long maxTimeout = -1;
                for (String t : tokens) {
                    long to;
                    try { to = StpUtil.getTokenTimeout(t); }
                    catch (Exception ignored) { continue; }
                    if (to > 0) {
                        activeCount++;
                        if (to > maxTimeout) {
                            maxTimeout = to;
                            freshestToken = t;
                        }
                    }
                }

                // 登录时间：用最新 token 推算（now - 已用时长）。session.getCreateTime() 是
                // 账号会话的首次创建时间，多次登录会复用，不能代表本次登录时间。
                long configTimeout = SaManager.getConfig().getTimeout();
                long loginMillis;
                if (freshestToken != null && maxTimeout > 0 && configTimeout > 0) {
                    long elapsedSec = Math.max(0, configTimeout - maxTimeout);
                    loginMillis = System.currentTimeMillis() - elapsedSec * 1000L;
                } else {
                    loginMillis = session.getCreateTime();
                }

                Map<String, Object> user = new LinkedHashMap<>();
                user.put("userId", loginId);
                user.put("username", username != null ? username : "");
                user.put("realName", realName != null ? realName : "");
                user.put("tokenCount", activeCount);
                user.put("tokenValue", freshestToken != null ? freshestToken : "");
                user.put("loginTime", sdf.format(new Date(loginMillis)));
                user.put("timeout", maxTimeout);
                users.add(user);
            } catch (Exception e) {
                // 会话可能已过期，跳过
                log.debug("Skip invalid session: {}", sessionId);
            }
        }

        // 按登录时间倒序
        users.sort((a, b) -> String.valueOf(b.get("loginTime")).compareTo(String.valueOf(a.get("loginTime"))));

        // 手动分页
        int total = users.size();
        int from = Math.min((pageNum - 1) * pageSize, total);
        int to = Math.min(from + pageSize, total);

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("list", users.subList(from, to));
        result.put("total", total);
        return Result.ok(result);
    }

@Transactional(rollbackFor = Exception.class)
    public String saveProvider(String id, String vendor, String name, List<String> modalities,
                               boolean enabled, Integer sort, Map<String, Object> values,
                               List<String> models, String tenant) {
        VendorSpec spec = ModelProviderDescriptors.get(vendor);
        if (spec == null) {
            throw new BizException("SYSA001", "Unknown model vendor: " + vendor);
        }
        ProviderDescriptor descriptor = spec.descriptor();

        ModelProviderPO po = (id == null || id.isBlank()) ? null : providerDao.selectById(id);
        Map<String, Object> stored = parse(po == null ? null : po.getConfigJson());

        Map<String, Object> merged = new LinkedHashMap<>(stored);
        if (values != null) {
            for (FieldSpec f : descriptor.getFields()) {
                Object incoming = values.get(f.key());
                if (f.secret()) {
                    String s = incoming == null ? null : String.valueOf(incoming);
                    if (s == null || s.isBlank() || MASK.equals(s)) {
                        continue; // keep stored secret
                    }
                    merged.put(f.key(), s);
                } else if (values.containsKey(f.key())) {
                    merged.put(f.key(), incoming);
                }
            }
        }

        String json;
        try {
            json = crypto.encrypt(objectMapper.writeValueAsString(merged));
        } catch (Exception e) {
            throw new BizException("SYSA002", "Invalid model config: " + e.getMessage());
        }

        String modalitiesCsv = modalities == null ? null : String.join(",", modalities);
        String modelsJson = writeModels(models);
        if (po == null) {
            po = new ModelProviderPO();
            po.setTenantId(tenant);
            po.setScope("0".equals(tenant) ? "GLOBAL" : "TENANT");
            po.setVendor(spec.vendor().name());
            po.setName(name);
            po.setModalities(modalitiesCsv);
            po.setConfigJson(json);
            po.setModels(modelsJson);
            po.setEnabled(enabled ? 1 : 0);
            po.setSort(sort == null ? 0 : sort);
            providerDao.insert(po);
        } else {
            po.setVendor(spec.vendor().name());
            po.setName(name);
            po.setModalities(modalitiesCsv);
            po.setConfigJson(json);
            po.setModels(modelsJson);
            po.setEnabled(enabled ? 1 : 0);
            po.setSort(sort == null ? po.getSort() : sort);
            providerDao.updateById(po);
        }
        log.info("[model] saved provider {} vendor={} enabled={}", po.getId(), vendor, enabled);
        return po.getId();
    }

@Override
        public void run() {
            if (message == null || message.isEmpty()) {
                System.err.println(Ansi.fail("Missing message. Usage: mate ai chat \"your question\" [--resume <id>]"));
                return;
            }
            String endpoint = resolveEndpoint(service);
            String question = String.join(" ", message);
            String sessionId = (conversationId != null && !forceNew)
                    ? conversationId : AiSessionStore.newId();
            AiSessionStore.Session session = AiSessionStore.loadOrCreate(sessionId);
            if (conversationId != null && !forceNew && AiSessionStore.load(sessionId) != null) {
                System.out.println(Ansi.muted("↻ resuming " + sessionId
                        + " (" + session.turns.size() / 2 + " prior turns)"));
            }

            Map<String, Object> body = new LinkedHashMap<>();
            body.put("message", question);
            body.put("conversationId", sessionId);

            JsonHttpClient http = new JsonHttpClient();
            Spinner spinner = new Spinner("thinking");
            boolean[] firstToken = {false};
            StringBuilder reply = new StringBuilder();
            spinner.start();
            try {
                // Try streaming first (SSE), with one retry if no token arrives in time.
                boolean streamed = false;
                for (int attempt = 1; attempt <= STREAM_RETRIES && !streamed; attempt++) {
                    streamed = http.postStream(endpoint + "/api/v1/ai/chat/stream", body, token -> {
                        if (!firstToken[0]) {
                            spinner.stop();
                            firstToken[0] = true;
                        }
                        System.out.print(token);
                        System.out.flush();
                        reply.append(token);
                    }, FIRST_TOKEN_TIMEOUT_MS);
                    if (!streamed && attempt < STREAM_RETRIES) {
                        try {
                            Thread.sleep(RETRY_BACKOFF_MS);
                        } catch (InterruptedException ie) {
                            Thread.currentThread().interrupt();
                            break;
                        }
                    }
                }
                if (!streamed) {
                    // Streaming unavailable (older service / timeout) → blocking fallback.
                    spinner.stop();
                    Map<String, Object> resp = http.postJson(endpoint + "/api/v1/ai/chat", body);
                    Object data = resp.get("data");
                    reply.append(data == null ? "" : data);
                    System.out.println(data == null ? Ansi.muted("(empty response)") : data);
                } else {
                    System.out.println();
                }
                AiSessionStore.record(session, question, reply.toString());
                System.out.println(Ansi.muted("session: " + sessionId + "   (resume: mate ai chat --resume "
                        + sessionId + " \"...\")"));
            } catch (Exception e) {
                spinner.stop();
                if (firstToken[0]) {
                    System.out.println();
                }
                System.err.println(Ansi.fail("Chat failed: ") + e.getMessage());
            }
        }

