@GetMapping("/cache/keys/{key}")
    public Result<Map<String, Object>> cacheKeyDetail(@PathVariable String key) {
        Map<String, Object> detail = new LinkedHashMap<>();
        detail.put("key", key);

        DataType type = stringRedisTemplate.type(key);
        if (type == null || type == DataType.NONE) {
            return Result.fail("Key not found");
        }
        detail.put("type", type.code());
        Long ttl = stringRedisTemplate.getExpire(key, TimeUnit.SECONDS);
        detail.put("ttl", ttl != null ? ttl : -2);

        // Memory usage
        try {
            Long memUsage = stringRedisTemplate.execute((RedisConnection conn) -> {
                Object result = conn.execute("MEMORY",
                        "USAGE".getBytes(StandardCharsets.UTF_8),
                        key.getBytes(StandardCharsets.UTF_8));
                if (result instanceof Long) return (Long) result;
                if (result instanceof Number) return ((Number) result).longValue();
                return null;
            });
            detail.put("size", memUsage != null ? formatBytes(memUsage) : "-");
        } catch (Exception e) {
            detail.put("size", "-");
        }

        // Read value based on type
        String value;
        try {
            value = switch (type) {
                case STRING -> stringRedisTemplate.opsForValue().get(key);
                case HASH -> {
                    Map<Object, Object> entries = stringRedisTemplate.opsForHash().entries(key);
                    yield mapToJson(entries);
                }
                case LIST -> {
                    List<String> list = stringRedisTemplate.opsForList().range(key, 0, 99);
                    yield list != null ? list.toString() : "[]";
                }
                case SET -> {
                    Set<String> members = stringRedisTemplate.opsForSet().members(key);
                    yield members != null ? members.toString() : "[]";
                }
                case ZSET -> {
                    Set<String> zMembers = stringRedisTemplate.opsForZSet().range(key, 0, 99);
                    yield zMembers != null ? zMembers.toString() : "[]";
                }
                default -> "(unsupported type)";
            };
        } catch (Exception e) {
            value = "(error reading value: " + e.getMessage() + ")";
        }

        if (value != null && value.length() > MAX_VALUE_PREVIEW) {
            value = value.substring(0, MAX_VALUE_PREVIEW) + "... (truncated)";
        }
        detail.put("value", value);

        return Result.ok(detail);
    }

@Override
        public void run() {
            try (RedisConnection redis = new RedisConnection()) {
                if (!usePattern) {
                    // Single key delete
                    if (dryRun) {
                        System.out.println("[dry-run] Would delete: " + key);
                        return;
                    }
                    redis.sendCommand("DEL", key);
                    Object reply = redis.readReply();
                    long deleted = reply instanceof Long l ? l : 0;
                    if (deleted > 0) {
                        System.out.println("Deleted: " + key);
                    } else {
                        System.out.println("Key not found: " + key);
                    }
                } else {
                    // Pattern-based delete using SCAN
                    List<String> toDelete = new ArrayList<>();
                    String cursor = "0";
                    do {
                        redis.sendCommand("SCAN", cursor, "MATCH", key, "COUNT", "100");
                        Object reply = redis.readReply();
                        if (reply instanceof List<?> arr && arr.size() == 2) {
                            cursor = String.valueOf(arr.get(0));
                            if (arr.get(1) instanceof List<?> keys) {
                                for (Object k : keys) {
                                    toDelete.add(String.valueOf(k));
                                }
                            }
                        } else {
                            break;
                        }
                    } while (!"0".equals(cursor));

                    if (toDelete.isEmpty()) {
                        System.out.println("No keys matching pattern: " + key);
                        return;
                    }

                    if (dryRun) {
                        System.out.println("[dry-run] Would delete " + toDelete.size() + " key(s):");
                        toDelete.forEach(k -> System.out.println("  " + k));
                        return;
                    }

                    int deleted = 0;
                    for (String k : toDelete) {
                        redis.sendCommand("DEL", k);
                        Object reply = redis.readReply();
                        if (reply instanceof Long l && l > 0) deleted++;
                    }
                    System.out.println("Deleted " + deleted + " key(s) matching '" + key + "'");
                }
            } catch (IOException e) {
                System.err.println(Ansi.fail("Redis error: " + e.getMessage()));
            }
        }
